/** The apue client runtime (template; the generator nests its body in the generated class). */
public final class Runtime {
  private Runtime() {}

  // ---- apue runtime: begin ----

  static final String STREAM_JSON = "application/apue+json";
  static final String PROBLEM_JSON = "application/problem+json";
  static final String ACCEPT = "application/apue+json, application/json;q=0.9, application/problem+json;q=0.8";
  static final int MAX_GET_URL = 2048;
  static final int MSG = 0x00, END = 0x01, BLOB = 0x02;
  static final int FLAG_LAST = 0x02;
  static final int BLOB_CHUNK = 64 * 1024;
  /** Largest message (JSON plus its blobs) or unary body accepted from a server. */
  static final int MAX_MESSAGE = 64 * 1024 * 1024;
  static final String DEADLINE_EXCEEDED = "https://apue.dev/problems/deadline-exceeded";

  /** An RFC 9457 problem: the call failed with {@code status} (HTTP semantics). */
  public static final class ApueException extends RuntimeException {
    private static final long serialVersionUID = 1L;
    private final int status;
    private final transient Map<String, Object> problem;

    public ApueException(int status, Map<String, ?> problem) {
      super(message(status, problem));
      this.status = status;
      this.problem = problem == null ? Map.of() : Collections.unmodifiableMap(new LinkedHashMap<>(problem));
    }

    static ApueException of(int status, String type, String title, String detail) {
      Map<String, Object> problem = new LinkedHashMap<>();
      if (type != null) problem.put("type", type);
      problem.put("title", title);
      problem.put("status", (long) status);
      if (detail != null) problem.put("detail", detail);
      return new ApueException(status, problem);
    }

    /** A malformed or unexpected response (502). */
    static ApueException badGateway(String title, String detail) {
      return of(502, null, title, detail);
    }

    private static String message(int status, Map<String, ?> problem) {
      Object title = problem == null ? null : problem.get("title");
      Object detail = problem == null ? null : problem.get("detail");
      return status + " " + (title instanceof String ? title : reason(status)) + (detail instanceof String ? ": " + detail : "");
    }

    /** The HTTP status code (from the response or the END frame). */
    public int status() {
      return status;
    }

    /** The problem type URI; {@code about:blank} for generic errors. */
    public String type() {
      return problem.get("type") instanceof String type ? type : "about:blank";
    }

    public String title() {
      return problem.get("title") instanceof String title ? title : reason(status);
    }

    /** The occurrence's explanation, or null. */
    public String detail() {
      return problem.get("detail") instanceof String detail ? detail : null;
    }

    /** apue extension: whether the same call may succeed if retried. */
    public boolean retryable() {
      return Boolean.TRUE.equals(problem.get("retryable"));
    }

    /** The whole problem object as parsed JSON (extension members such as {@code fields} included). */
    public Map<String, Object> problem() {
      return problem;
    }
  }

  static String reason(int status) {
    switch (status) {
      case 400: return "Bad Request";
      case 401: return "Unauthorized";
      case 403: return "Forbidden";
      case 404: return "Not Found";
      case 405: return "Method Not Allowed";
      case 408: return "Request Timeout";
      case 409: return "Conflict";
      case 410: return "Gone";
      case 412: return "Precondition Failed";
      case 413: return "Content Too Large";
      case 415: return "Unsupported Media Type";
      case 416: return "Range Not Satisfiable";
      case 422: return "Unprocessable Content";
      case 424: return "Failed Dependency";
      case 429: return "Too Many Requests";
      case 500: return "Internal Server Error";
      case 501: return "Not Implemented";
      case 502: return "Bad Gateway";
      case 503: return "Service Unavailable";
      case 504: return "Gateway Timeout";
      case 507: return "Insufficient Storage";
      default: return "Error";
    }
  }

  static ApueException problem(int status, byte[] body) {
    Object parsed = null;
    try {
      parsed = body.length == 0 ? null : Json.parse(body);
    } catch (IllegalArgumentException e) {
      parsed = null;
    }
    if (parsed instanceof Map<?, ?> map && map.keySet().stream().allMatch(k -> k instanceof String)) {
      @SuppressWarnings("unchecked")
      Map<String, Object> problem = (Map<String, Object>) map;
      return new ApueException(status, problem);
    }
    return ApueException.of(status, null, reason(status), null);
  }

  // ---- JSON ----------------------------------------------------------------------------------

  /**
   * JSON values as plain Java objects: {@code Map<String, Object>} (insertion-ordered), {@code
   * List<Object>}, {@code String}, {@code Long} (integers that fit), {@code Double}, {@code Boolean}
   * and {@code null}. {@link #write} produces canonical JSON (sorted keys, ECMAScript number
   * formatting, as RFC 8785), so GET URLs are deterministic cache keys.
   */
  public static final class Json {
    private Json() {}

    /** Parses one JSON text; IllegalArgumentException if it is not valid JSON. */
    public static Object parse(String text) {
      Parser parser = new Parser(text);
      parser.space();
      Object value = parser.value(0);
      parser.space();
      if (parser.at < text.length()) throw parser.error("trailing data");
      return value;
    }

    public static Object parse(byte[] utf8) {
      return parse(new String(utf8, StandardCharsets.UTF_8));
    }

    /** Canonical JSON: object keys sorted by UTF-16 code units, numbers as ECMAScript prints them. */
    public static String write(Object value) {
      StringBuilder out = new StringBuilder();
      write(value, out);
      return out.toString();
    }

    private static void write(Object value, StringBuilder out) {
      if (value == null) {
        out.append("null");
      } else if (value instanceof Boolean b) {
        out.append(b ? "true" : "false");
      } else if (value instanceof String s) {
        string(s, out);
      } else if (value instanceof Long || value instanceof Integer || value instanceof Short || value instanceof Byte) {
        out.append(((Number) value).longValue());
      } else if (value instanceof Double || value instanceof Float) {
        out.append(number(((Number) value).doubleValue()));
      } else if (value instanceof Map<?, ?> map) {
        TreeMap<String, Object> sorted = new TreeMap<>(); // String order = UTF-16 code unit order
        for (Map.Entry<?, ?> entry : map.entrySet()) {
          if (!(entry.getKey() instanceof String key)) throw new IllegalArgumentException("JSON object keys must be strings");
          sorted.put(key, entry.getValue());
        }
        out.append('{');
        boolean first = true;
        for (Map.Entry<String, Object> entry : sorted.entrySet()) {
          if (!first) out.append(',');
          first = false;
          string(entry.getKey(), out);
          out.append(':');
          write(entry.getValue(), out);
        }
        out.append('}');
      } else if (value instanceof Collection<?> list) {
        out.append('[');
        boolean first = true;
        for (Object item : list) {
          if (!first) out.append(',');
          first = false;
          write(item, out);
        }
        out.append(']');
      } else if (value instanceof byte[]) {
        throw new IllegalArgumentException("bytes are not JSON: they travel as uploads or BLOB frames where the schema says so");
      } else {
        throw new IllegalArgumentException("not JSON-serialisable: " + value.getClass().getName());
      }
    }

    private static void string(String s, StringBuilder out) {
      out.append('"');
      for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        switch (c) {
          case '"': out.append("\\\""); break;
          case '\\': out.append("\\\\"); break;
          case '\b': out.append("\\b"); break;
          case '\f': out.append("\\f"); break;
          case '\n': out.append("\\n"); break;
          case '\r': out.append("\\r"); break;
          case '\t': out.append("\\t"); break;
          default:
            if (c < 0x20) {
              out.append(String.format("\\u%04x", (int) c));
            } else if (Character.isHighSurrogate(c) && i + 1 < s.length() && Character.isLowSurrogate(s.charAt(i + 1))) {
              out.append(c).append(s.charAt(++i));
            } else if (Character.isSurrogate(c)) {
              out.append(String.format("\\u%04x", (int) c)); // lone surrogate, as JSON.stringify writes it
            } else {
              out.append(c);
            }
        }
      }
      out.append('"');
    }

    /** A finite double as ECMAScript's Number::toString prints it (shortest round-trip digits). */
    public static String number(double d) {
      if (!Double.isFinite(d)) throw new IllegalArgumentException("NaN and infinities are not JSON");
      if (d == 0) return "0"; // -0 too
      BigDecimal exact = new BigDecimal(d);
      BigDecimal best = null;
      for (int precision = 1; precision <= 17 && best == null; precision++) {
        BigDecimal low = exact.round(new MathContext(precision, RoundingMode.FLOOR));
        BigDecimal high = exact.round(new MathContext(precision, RoundingMode.CEILING));
        boolean lowOk = low.doubleValue() == d;
        boolean highOk = high.doubleValue() == d;
        if (lowOk && highOk) {
          int cmp = exact.subtract(low).abs().compareTo(high.subtract(exact).abs());
          best = cmp < 0 ? low : cmp > 0 ? high : low.unscaledValue().testBit(0) ? high : low;
        } else if (lowOk) {
          best = low;
        } else if (highOk) {
          best = high;
        }
      }
      if (best == null) best = exact.round(MathContext.DECIMAL64); // unreachable: 17 digits always round-trip
      best = best.stripTrailingZeros();
      String digits = best.unscaledValue().abs().toString();
      int k = digits.length();
      int n = k - best.scale(); // value = digits * 10^(n - k)
      String sign = d < 0 ? "-" : "";
      if (k <= n && n <= 21) return sign + digits + "0".repeat(n - k);
      if (0 < n && n <= 21) return sign + digits.substring(0, n) + "." + digits.substring(n);
      if (-6 < n && n <= 0) return sign + "0." + "0".repeat(-n) + digits;
      int e = n - 1;
      String exponent = "e" + (e < 0 ? "-" : "+") + Math.abs(e);
      return sign + digits.charAt(0) + (k == 1 ? "" : "." + digits.substring(1)) + exponent;
    }

    private static final class Parser {
      private static final int MAX_DEPTH = 512;
      final String text;
      int at;

      Parser(String text) {
        this.text = text;
      }

      IllegalArgumentException error(String what) {
        return new IllegalArgumentException("invalid JSON at " + at + ": " + what);
      }

      void space() {
        while (at < text.length()) {
          char c = text.charAt(at);
          if (c != ' ' && c != '\t' && c != '\n' && c != '\r') break;
          at++;
        }
      }

      Object value(int depth) {
        if (depth > MAX_DEPTH) throw error("nested too deeply");
        if (at >= text.length()) throw error("unexpected end");
        char c = text.charAt(at);
        switch (c) {
          case '{': {
            at++;
            Map<String, Object> map = new LinkedHashMap<>();
            space();
            if (peek('}')) return map;
            while (true) {
              space();
              if (at >= text.length() || text.charAt(at) != '"') throw error("expected a key");
              String key = string();
              space();
              expect(':');
              space();
              map.put(key, value(depth + 1));
              space();
              if (peek('}')) return map;
              expect(',');
            }
          }
          case '[': {
            at++;
            List<Object> list = new ArrayList<>();
            space();
            if (peek(']')) return list;
            while (true) {
              space();
              list.add(value(depth + 1));
              space();
              if (peek(']')) return list;
              expect(',');
            }
          }
          case '"':
            return string();
          case 't':
            literal("true");
            return Boolean.TRUE;
          case 'f':
            literal("false");
            return Boolean.FALSE;
          case 'n':
            literal("null");
            return null;
          default:
            return number();
        }
      }

      boolean peek(char c) {
        if (at < text.length() && text.charAt(at) == c) {
          at++;
          return true;
        }
        return false;
      }

      void expect(char c) {
        if (!peek(c)) throw error("expected '" + c + "'");
      }

      void literal(String word) {
        if (!text.startsWith(word, at)) throw error("unexpected token");
        at += word.length();
      }

      String string() {
        at++; // opening quote
        StringBuilder out = new StringBuilder();
        while (true) {
          if (at >= text.length()) throw error("unterminated string");
          char c = text.charAt(at++);
          if (c == '"') return out.toString();
          if (c < 0x20) throw error("control character in string");
          if (c != '\\') {
            out.append(c);
            continue;
          }
          if (at >= text.length()) throw error("unterminated escape");
          char e = text.charAt(at++);
          switch (e) {
            case '"': out.append('"'); break;
            case '\\': out.append('\\'); break;
            case '/': out.append('/'); break;
            case 'b': out.append('\b'); break;
            case 'f': out.append('\f'); break;
            case 'n': out.append('\n'); break;
            case 'r': out.append('\r'); break;
            case 't': out.append('\t'); break;
            case 'u': {
              if (at + 4 > text.length()) throw error("short \\u escape");
              int code = 0;
              for (int i = 0; i < 4; i++) {
                int digit = Character.digit(text.charAt(at++), 16);
                if (digit < 0) throw error("bad \\u escape");
                code = code * 16 + digit;
              }
              out.append((char) code);
              break;
            }
            default:
              throw error("bad escape");
          }
        }
      }

      Object number() {
        int start = at;
        peek('-');
        if (peek('0')) {
          // no leading zeros
        } else if (at < text.length() && text.charAt(at) >= '1' && text.charAt(at) <= '9') {
          digits();
        } else {
          throw error("unexpected character");
        }
        boolean integral = true;
        if (peek('.')) {
          integral = false;
          if (digits() == 0) throw error("expected digits");
        }
        if (at < text.length() && (text.charAt(at) == 'e' || text.charAt(at) == 'E')) {
          at++;
          integral = false;
          if (!peek('+')) peek('-');
          if (digits() == 0) throw error("expected digits");
        }
        String token = text.substring(start, at);
        if (integral) {
          try {
            return Long.parseLong(token);
          } catch (NumberFormatException e) {
            // beyond long: a double, as JavaScript reads it
          }
        }
        return Double.parseDouble(token);
      }

      int digits() {
        int start = at;
        while (at < text.length() && text.charAt(at) >= '0' && text.charAt(at) <= '9') at++;
        return at - start;
      }
    }

    // -- conversions used by the generated code (server data: a mismatch is a 502) --

    static ApueException unexpected(String expected, Object got) {
      String kind = got == null ? "null" : got instanceof Map ? "object" : got instanceof List ? "array" : got instanceof String ? "string"
          : got instanceof Number ? "number" : got instanceof Boolean ? "boolean" : got instanceof byte[] ? "bytes" : got.getClass().getSimpleName();
      return ApueException.badGateway("Unexpected Output", "expected " + expected + ", got " + kind);
    }

    @SuppressWarnings("unchecked")
    public static Map<String, Object> object(Object value) {
      if (value instanceof Map<?, ?> map) return (Map<String, Object>) map;
      throw unexpected("object", value);
    }

    /** A required member (may be JSON null if the schema allows it). */
    public static Object required(Map<String, Object> object, String key) {
      if (!object.containsKey(key)) throw ApueException.badGateway("Unexpected Output", "missing member " + key);
      return object.get(key);
    }

    /** An optional member: null when absent. */
    public static <T> T optional(Map<String, Object> object, String key, Function<Object, T> decode) {
      Object value = object.get(key);
      return value == null ? null : decode.apply(value);
    }

    /** An optional, nullable member: null when absent, Optional.empty() when JSON null. */
    public static <T> Optional<T> optionalNullable(Map<String, Object> object, String key, Function<Object, T> decode) {
      if (!object.containsKey(key)) return null;
      Object value = object.get(key);
      return value == null ? Optional.empty() : Optional.of(decode.apply(value));
    }

    public static <A, B> B orNull(A value, Function<A, B> convert) {
      return value == null ? null : convert.apply(value);
    }

    public static String string(Object value) {
      if (value instanceof String s) return s;
      throw unexpected("string", value);
    }

    public static boolean bool(Object value) {
      if (value instanceof Boolean b) return b;
      throw unexpected("boolean", value);
    }

    public static long int64(Object value) {
      if (value instanceof Long l) return l;
      if (value instanceof Double d && d == Math.rint(d) && Math.abs(d) < 0x1p63) return d.longValue();
      throw unexpected("integer", value);
    }

    public static double float64(Object value) {
      if (value instanceof Number n) return n.doubleValue();
      throw unexpected("number", value);
    }

    public static byte[] bytes(Object value) {
      if (value instanceof byte[] b) return b;
      throw unexpected("bytes", value);
    }

    /** A number to send: finite only. */
    public static double finite(double value) {
      if (!Double.isFinite(value)) throw new IllegalArgumentException("NaN and infinities are not JSON");
      return value;
    }

    public static <T> List<T> decodeList(Object value, Function<Object, T> decode) {
      if (!(value instanceof List<?> list)) throw unexpected("array", value);
      List<T> out = new ArrayList<>(list.size());
      for (Object item : list) out.add(decode.apply(item));
      return Collections.unmodifiableList(out);
    }

    public static <T> List<Object> encodeList(List<T> value, Function<T, Object> encode) {
      List<Object> out = new ArrayList<>(value.size());
      for (T item : value) out.add(encode.apply(item));
      return out;
    }

    /** Request stream inputs, encoded as they are taken. */
    public static <T> Iterator<Object> encodeEach(Iterable<T> inputs, Function<T, Object> encode) {
      Iterator<T> source = inputs.iterator();
      return new Iterator<>() {
        public boolean hasNext() {
          return source.hasNext();
        }

        public Object next() {
          return encode.apply(source.next());
        }
      };
    }

    /**
     * A copy of a value for a schema position of unknown type: only JSON types (maps with string
     * keys, lists, strings, numbers, booleans, null) - bytes travel only where the schema says so.
     */
    public static Object plain(Object value) {
      if (value == null || value instanceof String || value instanceof Boolean || value instanceof Long) return value;
      if (value instanceof Integer || value instanceof Short || value instanceof Byte) return ((Number) value).longValue();
      if (value instanceof Double || value instanceof Float) return finite(((Number) value).doubleValue());
      if (value instanceof Map<?, ?> map) {
        Map<String, Object> out = new LinkedHashMap<>();
        for (Map.Entry<?, ?> entry : map.entrySet()) {
          if (!(entry.getKey() instanceof String key)) throw new IllegalArgumentException("JSON object keys must be strings");
          out.put(key, plain(entry.getValue()));
        }
        return out;
      }
      if (value instanceof Collection<?> list) {
        List<Object> out = new ArrayList<>(list.size());
        for (Object item : list) out.add(plain(item));
        return out;
      }
      throw new IllegalArgumentException("not a JSON value: " + value.getClass().getName());
    }
  }

  // ---- framing and binary values ----------------------------------------------------------------

  static ByteBuffer header(int type, int flags, int length) {
    ByteBuffer header = ByteBuffer.allocate(8);
    header.put((byte) type).put((byte) flags).putShort((short) 0).putInt(length).flip();
    return header;
  }

  /** byte[] -> {"$blob": k} (sent as BLOB frames first); look-alikes escaped as {"$lit": ...}. */
  static Object split(Object value, List<byte[]> blobs) {
    if (value instanceof byte[] bytes) {
      blobs.add(bytes);
      return Map.of("$blob", (long) (blobs.size() - 1));
    }
    if (value instanceof List<?> list) {
      List<Object> out = new ArrayList<>(list.size());
      for (Object item : list) out.add(split(item, blobs));
      return out;
    }
    if (value instanceof Map<?, ?> map) {
      if (map.size() == 1) {
        Object key = map.keySet().iterator().next();
        if ("$blob".equals(key) || "$lit".equals(key)) return Collections.singletonMap("$lit", map);
      }
      Map<Object, Object> out = new LinkedHashMap<>();
      for (Map.Entry<?, ?> entry : map.entrySet()) out.put(entry.getKey(), split(entry.getValue(), blobs));
      return out;
    }
    return value;
  }

  /** Resolves {"$blob": k} references and {"$lit": ...} escapes of a received message. */
  static Object restore(Object value, List<byte[]> blobs, Set<Integer> used) {
    if (value instanceof List<?> list) {
      List<Object> out = new ArrayList<>(list.size());
      for (Object item : list) out.add(restore(item, blobs, used));
      return out;
    }
    if (!(value instanceof Map<?, ?> map)) return value;
    if (map.size() == 1 && map.containsKey("$lit")) return map.get("$lit");
    if (map.size() == 1 && map.containsKey("$blob")) {
      Object index = map.get("$blob");
      if (!(index instanceof Long i) || i < 0 || i >= blobs.size() || used.contains(i.intValue())) {
        throw ApueException.badGateway("Malformed Stream", "invalid blob reference " + Json.write(index));
      }
      used.add(i.intValue());
      return blobs.get(i.intValue());
    }
    Map<Object, Object> out = new LinkedHashMap<>();
    for (Map.Entry<?, ?> entry : map.entrySet()) out.put(entry.getKey(), restore(entry.getValue(), blobs, used));
    return out;
  }

  /** The frames of one request stream message: BLOB chunks for its bytes, then the MSG. */
  static List<ByteBuffer> messageFrames(Object value, boolean blobs) {
    List<ByteBuffer> frames = new ArrayList<>();
    List<byte[]> found = new ArrayList<>();
    Object json = blobs ? split(value, found) : value;
    for (byte[] blob : found) {
      if (blob.length == 0) frames.add(header(BLOB, FLAG_LAST, 0));
      for (int offset = 0; offset < blob.length; offset += BLOB_CHUNK) {
        int end = Math.min(offset + BLOB_CHUNK, blob.length);
        frames.add(header(BLOB, end == blob.length ? FLAG_LAST : 0, end - offset));
        frames.add(ByteBuffer.wrap(blob, offset, end - offset));
      }
    }
    byte[] payload = Json.write(json).getBytes(StandardCharsets.UTF_8);
    frames.add(header(MSG, 0, payload.length));
    frames.add(ByteBuffer.wrap(payload));
    return frames;
  }

  /**
   * A request body of frames, pulled from the caller's inputs on a thread of its own (the inputs
   * may block; HttpClient's threads must not), as fast as HttpClient asks for data.
   */
  static final class FramePublisher implements Flow.Publisher<ByteBuffer> {
    private final Iterator<?> inputs;
    private final boolean blobs;
    private boolean subscribed;
    /** An exception thrown by the caller's inputs: rethrown by the call. */
    volatile RuntimeException failure;

    FramePublisher(Iterator<?> inputs, boolean blobs) {
      this.inputs = inputs;
      this.blobs = blobs;
    }

    @Override
    public void subscribe(Flow.Subscriber<? super ByteBuffer> subscriber) {
      synchronized (this) {
        if (subscribed) {
          subscriber.onSubscribe(new Flow.Subscription() {
            public void request(long n) {}

            public void cancel() {}
          });
          subscriber.onError(new IOException("a request stream can't be sent twice"));
          return;
        }
        subscribed = true;
      }
      subscriber.onSubscribe(new Pump(subscriber));
    }

    private final class Pump implements Flow.Subscription, Runnable {
      private final Flow.Subscriber<? super ByteBuffer> subscriber;
      private long demand;
      private boolean cancelled;
      private Thread thread;

      Pump(Flow.Subscriber<? super ByteBuffer> subscriber) {
        this.subscriber = subscriber;
      }

      @Override
      public synchronized void request(long n) {
        if (n <= 0) {
          cancelled = true;
          subscriber.onError(new IllegalArgumentException("non-positive request"));
          return;
        }
        demand = demand + n < 0 ? Long.MAX_VALUE : demand + n;
        if (thread == null) {
          thread = new Thread(this, "apue-request-stream");
          thread.setDaemon(true);
          thread.start();
        }
        notifyAll();
      }

      @Override
      public synchronized void cancel() {
        cancelled = true;
        notifyAll();
      }

      private boolean take() throws InterruptedException {
        synchronized (this) {
          while (demand == 0 && !cancelled) wait();
          if (cancelled) return false;
          demand--;
          return true;
        }
      }

      private boolean emit(List<ByteBuffer> buffers) throws InterruptedException {
        for (ByteBuffer buffer : buffers) {
          if (!take()) return false;
          subscriber.onNext(buffer);
        }
        return true;
      }

      @Override
      public void run() {
        try {
          while (inputs.hasNext()) {
            if (!emit(messageFrames(inputs.next(), blobs))) return;
          }
          byte[] end = "{\"status\":200}".getBytes(StandardCharsets.UTF_8);
          if (!emit(List.of(header(END, 0, end.length), ByteBuffer.wrap(end)))) return;
          subscriber.onComplete();
        } catch (RuntimeException e) {
          failure = e;
          subscriber.onError(new IOException("request stream input failed: " + e, e));
        } catch (InterruptedException e) {
          subscriber.onError(new InterruptedIOException("request stream interrupted"));
        }
      }
    }
  }

  // ---- responses --------------------------------------------------------------------------------

  /** A response whose body may have been read already (409 probing). */
  record Res(int status, HttpHeaders headers, InputStream body, HttpClient.Version version) {
    String mediaType() {
      return headers.firstValue("content-type").map(v -> v.split(";", 2)[0].trim().toLowerCase(java.util.Locale.ROOT)).orElse("");
    }
  }

  static byte[] readBody(InputStream in, int limit) {
    try (in) {
      byte[] body = in.readNBytes(limit + 1);
      if (body.length > limit) throw ApueException.badGateway("Bad Gateway", "response body larger than " + limit + " bytes");
      return body;
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  /** The values of a response: one for a JSON body, each MSG for a framed one; END errors thrown. */
  static final class Reader implements AutoCloseable {
    private static final Object DONE = new Object();
    private final Res res;
    private final boolean blobs;
    private final boolean framed;
    private Object single;
    private boolean done;

    Reader(Res res, boolean blobs) {
      this.res = res;
      this.blobs = blobs;
      String type = res.mediaType();
      this.framed = res.status() < 400 && type.equals(STREAM_JSON);
      if (!framed) {
        byte[] body = readBody(res.body(), MAX_MESSAGE);
        done = true;
        if (res.status() >= 400 || type.equals(PROBLEM_JSON)) throw problem(res.status(), body);
        try {
          single = body.length == 0 ? null : Json.parse(body);
        } catch (IllegalArgumentException e) {
          throw ApueException.badGateway("Bad Gateway", "response is not JSON: " + e.getMessage());
        }
      } else {
        single = DONE;
      }
    }

    /** The next value, or {@link #DONE}. */
    Object next() {
      if (!framed) {
        Object value = single;
        single = DONE;
        return value;
      }
      if (done) return DONE;
      try {
        return frame();
      } catch (IOException e) {
        close();
        throw new UncheckedIOException(e);
      } catch (RuntimeException e) {
        close();
        throw e;
      }
    }

    private Object frame() throws IOException {
      InputStream in = res.body();
      List<byte[]> found = new ArrayList<>();
      ByteArrayOutputStream pending = null;
      long total = 0;
      while (true) {
        byte[] head = in.readNBytes(8);
        if (head.length == 0) throw ApueException.badGateway("Truncated Stream", "response ended without END frame");
        if (head.length < 8) throw ApueException.badGateway("Truncated Stream", "incomplete frame header");
        ByteBuffer h = ByteBuffer.wrap(head);
        int type = h.get() & 0xff;
        int flags = h.get() & 0xff;
        h.getShort(); // lane: 0 for single calls
        long length = h.getInt() & 0xffffffffL;
        if (length > MAX_MESSAGE || (type == BLOB && total + length > MAX_MESSAGE)) {
          throw ApueException.badGateway("Malformed Stream", "message larger than " + MAX_MESSAGE + " bytes");
        }
        if (type != MSG && type != END && type != BLOB) {
          in.skipNBytes(length); // HEARTBEAT, CHECKPOINT, unknown types: ignored
          continue;
        }
        byte[] payload = in.readNBytes((int) length);
        if (payload.length < length) throw ApueException.badGateway("Truncated Stream", "incomplete frame");
        if (type == BLOB) {
          if (pending == null) pending = new ByteArrayOutputStream();
          pending.write(payload);
          total += length;
          if ((flags & FLAG_LAST) != 0) {
            found.add(pending.toByteArray());
            pending = null;
          }
        } else if (type == MSG) {
          if (pending != null) throw ApueException.badGateway("Malformed Stream", "MSG frame inside an unfinished blob");
          Object value = parsePayload(payload);
          if (!blobs) {
            if (!found.isEmpty()) throw ApueException.badGateway("Malformed Stream", "unexpected BLOB frames");
            return value;
          }
          Set<Integer> used = new HashSet<>();
          value = restore(value, found, used);
          if (used.size() != found.size()) throw ApueException.badGateway("Malformed Stream", "message references " + used.size() + " of " + found.size() + " blobs");
          return value;
        } else {
          done = true;
          Map<String, Object> info = Json.object(parsePayload(payload));
          close();
          int status = info.get("status") instanceof Long s ? s.intValue() : 200;
          if (status >= 400) {
            Object problem = info.get("problem");
            @SuppressWarnings("unchecked")
            Map<String, Object> map = problem instanceof Map ? (Map<String, Object>) problem : Map.of("title", reason(status));
            throw new ApueException(status, map);
          }
          return DONE;
        }
      }
    }

    private static Object parsePayload(byte[] payload) {
      try {
        return Json.parse(payload);
      } catch (IllegalArgumentException e) {
        throw ApueException.badGateway("Malformed Stream", "frame payload is not JSON: " + e.getMessage());
      }
    }

    /** The first value; reads to the end (END errors are thrown). */
    Object only() {
      try {
        Object first = next();
        while (next() != DONE) {
          // further messages of a unary response are ignored
        }
        return first == DONE ? null : first;
      } finally {
        close();
      }
    }

    @Override
    public void close() {
      done = true;
      try {
        res.body().close(); // before the end: resets the HTTP/2 stream, the connection stays
      } catch (IOException e) {
        // closing is best effort
      }
    }
  }

  /**
   * Server, bidi stream outputs as they arrive: an Iterator (and a single-use Iterable). Errors -
   * including an error in the END frame after some items - are thrown from hasNext()/next(). Close
   * it to stop early (the HTTP/2 stream is reset, the server's handler is aborted, the connection
   * stays usable); it closes itself at the end.
   */
  public static final class Stream<T> implements Iterator<T>, Iterable<T>, AutoCloseable {
    private final Reader reader;
    private final Function<Object, T> decode;
    private final Runnable onClose;
    private Object next;
    private boolean fetched;
    private boolean iterated;
    private boolean closed;

    Stream(Reader reader, Function<Object, T> decode, Runnable onClose) {
      this.reader = reader;
      this.decode = decode;
      this.onClose = onClose;
    }

    @Override
    public boolean hasNext() {
      if (!fetched) {
        if (closed) return false;
        try {
          next = reader.next();
        } catch (RuntimeException e) {
          close();
          throw e;
        }
        fetched = true;
        if (next == Reader.DONE) close();
      }
      return next != Reader.DONE;
    }

    @Override
    public T next() {
      if (!hasNext()) throw new NoSuchElementException();
      fetched = false;
      try {
        return decode.apply(next);
      } catch (RuntimeException e) {
        close();
        throw e;
      }
    }

    /** This stream itself: it can be iterated once. */
    @Override
    public Iterator<T> iterator() {
      if (iterated) throw new IllegalStateException("a Stream can be iterated once");
      iterated = true;
      return this;
    }

    /** All remaining outputs. */
    public List<T> toList() {
      List<T> out = new ArrayList<>();
      while (hasNext()) out.add(next());
      return out;
    }

    /** The remaining outputs as a java.util.stream.Stream; closing it closes this. */
    public java.util.stream.Stream<T> stream() {
      return StreamSupport.stream(Spliterators.spliteratorUnknownSize(this, Spliterator.ORDERED), false).onClose(this::close);
    }

    @Override
    public void close() {
      if (closed) return;
      closed = true;
      reader.close();
      if (onClose != null) onClose.run();
    }
  }

  // ---- inputs and options -----------------------------------------------------------------------

  /** A file input ({@code t.file()}): bytes, a file, a stream, or an existing upload's id. */
  public static final class FileInput {
    private final byte[] bytes;
    private final Path path;
    private final InputStream stream;
    private final String upload;

    private FileInput(byte[] bytes, Path path, InputStream stream, String upload) {
      this.bytes = bytes;
      this.path = path;
      this.stream = stream;
      this.upload = upload;
    }

    public static FileInput of(byte[] data) {
      return new FileInput(Objects.requireNonNull(data, "data"), null, null, null);
    }

    /** A file, streamed from disk (never read into memory). */
    public static FileInput of(Path file) {
      return new FileInput(null, Objects.requireNonNull(file, "file"), null, null);
    }

    /** A stream, read once while uploading (single use). */
    public static FileInput of(InputStream in) {
      return new FileInput(null, null, Objects.requireNonNull(in, "in"), null);
    }

    /** Content uploaded before with {@code client.upload(...)} (the caller deletes it). */
    public static FileInput ofUpload(Map<String, ?> ref) {
      if (!(ref.get("$upload") instanceof String id)) throw new IllegalArgumentException("not an upload reference: " + ref);
      return new FileInput(null, null, null, id);
    }

    HttpRequest.BodyPublisher publisher() {
      if (bytes != null) return HttpRequest.BodyPublishers.ofByteArray(bytes);
      if (path != null) {
        try {
          return HttpRequest.BodyPublishers.ofFile(path);
        } catch (IOException e) {
          throw new UncheckedIOException(e);
        }
      }
      return HttpRequest.BodyPublishers.ofInputStream(() -> stream);
    }

    public static FileInput fromJson(Object value) {
      throw Json.unexpected("no file (files are inputs only)", value);
    }
  }

  /** Per-call options: a deadline and, for non-safe unary calls, the Idempotency-Key. Immutable. */
  public static final class CallOptions {
    public static final CallOptions DEFAULT = new CallOptions(null, null);
    private final Duration timeout;
    private final String idempotencyKey;

    private CallOptions(Duration timeout, String idempotencyKey) {
      this.timeout = timeout;
      this.idempotencyKey = idempotencyKey;
    }

    public CallOptions() {
      this(null, null);
    }

    /** Deadline: sent as {@code apue-timeout}; the server answers 504 after it passes. */
    public CallOptions timeout(Duration deadline) {
      if (deadline != null && (deadline.isNegative() || deadline.isZero())) throw new IllegalArgumentException("timeout must be positive");
      return new CallOptions(deadline, idempotencyKey);
    }

    /** The Idempotency-Key for this call (default: a random UUID); the same key replays the result. */
    public CallOptions idempotencyKey(String key) {
      if (key != null && !key.chars().allMatch(c -> c >= 0x20 && c <= 0x7e)) throw new IllegalArgumentException("Idempotency-Key must be printable ASCII");
      return new CallOptions(timeout, key);
    }
  }

  /** Client options (mutable builder; the client copies them). */
  public static final class Options {
    SSLContext sslContext;
    Supplier<String> authorization;
    int retries = 2;
    Duration backoff = Duration.ofMillis(100);
    Duration maxBackoff = Duration.ofSeconds(2);
    Duration connectTimeout = Duration.ofSeconds(10);
    Duration timeout;

    /** Trusts exactly the certificates in this PEM file (e.g. a private CA), instead of the JDK's. */
    public Options trustedCertificates(Path pem) {
      try (InputStream in = Files.newInputStream(pem)) {
        return trustedCertificates(in);
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
    }

    /** Trusts exactly the certificates in this PEM text, instead of the JDK's. */
    public Options trustedCertificates(String pem) {
      return trustedCertificates(new ByteArrayInputStream(pem.getBytes(StandardCharsets.US_ASCII)));
    }

    private Options trustedCertificates(InputStream pem) {
      try {
        KeyStore store = KeyStore.getInstance(KeyStore.getDefaultType());
        store.load(null, null);
        int i = 0;
        for (Certificate certificate : CertificateFactory.getInstance("X.509").generateCertificates(pem)) store.setCertificateEntry("ca" + i++, certificate);
        if (i == 0) throw new IllegalArgumentException("no certificate in PEM");
        TrustManagerFactory trust = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        trust.init(store);
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, trust.getTrustManagers(), null);
        this.sslContext = context;
        return this;
      } catch (GeneralSecurityException | IOException e) {
        throw new IllegalArgumentException("can't trust these certificates: " + e.getMessage(), e);
      }
    }

    public Options sslContext(SSLContext context) {
      this.sslContext = context;
      return this;
    }

    /** The Authorization header value for every request. */
    public Options authorization(String value) {
      return authorization(() -> value);
    }

    /** Asked before every request (e.g. for refreshed tokens); null sends none. */
    public Options authorization(Supplier<String> value) {
      this.authorization = value;
      return this;
    }

    /** Retries for safe and keyed calls (default 2). */
    public Options retries(int retries) {
      if (retries < 0) throw new IllegalArgumentException("retries must be >= 0");
      this.retries = retries;
      return this;
    }

    /** Base of the full-jitter backoff (default 100 ms): attempt n waits up to base*2^n. */
    public Options backoff(Duration base) {
      this.backoff = base;
      return this;
    }

    /** Cap for backoff and Retry-After (default 2 s). */
    public Options maxBackoff(Duration max) {
      this.maxBackoff = max;
      return this;
    }

    public Options connectTimeout(Duration timeout) {
      this.connectTimeout = timeout;
      return this;
    }

    /** How long to wait for response headers (default: no limit; a call's deadline sets its own). */
    public Options timeout(Duration timeout) {
      this.timeout = timeout;
      return this;
    }
  }

  /** An op as the generated client describes it. */
  static final class Op {
    final String name;
    final String effect;
    final String stream;
    /** The input has bytes or files (unary: uploads; request streams: BLOB frames). */
    final boolean bytesIn;
    /** The output has bytes (BLOB frames, $blob/$lit). */
    final boolean bytesOut;

    Op(String name, String effect, String stream, boolean bytesIn, boolean bytesOut) {
      this.name = name;
      this.effect = effect;
      this.stream = stream;
      this.bytesIn = bytesIn;
      this.bytesOut = bytesOut;
    }
  }

  // ---- downloads ---------------------------------------------------------------------------------

  /**
   * A {@code t.download()} output: {@link #url()} works as a plain link until {@link #expires()};
   * {@link #open()} resumes a lost connection with Range + If-Range and verifies the SHA-256.
   */
  public static final class Download {
    private final Map<String, Object> ref;
    private final Base client;
    private final String path;
    private final long size;
    private final String type;
    private final String sha256;
    private final Instant expires;

    Download(Map<String, Object> ref, Base client) {
      this.ref = ref;
      this.client = client;
      this.path = Json.string(Json.required(ref, "$download"));
      if (!path.startsWith("/")) throw ApueException.badGateway("Bad Gateway", "download path must be origin-relative");
      this.size = Json.int64(Json.required(ref, "size"));
      this.type = Json.string(Json.required(ref, "type"));
      this.sha256 = Json.optional(ref, "sha256", Json::string);
      Instant at;
      try {
        at = Instant.parse(Json.string(Json.required(ref, "expires")));
      } catch (java.time.format.DateTimeParseException e) {
        throw ApueException.badGateway("Unexpected Output", "download expiry is not a timestamp");
      }
      this.expires = at;
    }

    public static Download fromJson(Object value, Base client) {
      return new Download(Json.object(value), client);
    }

    /** The reference as it was on the wire. */
    public Map<String, Object> toJson() {
      return ref;
    }

    /** Absolute URL of the download (a capability: anyone with it can download until it expires). */
    public URI url() {
      return client.origin().resolve(path);
    }

    public String path() {
      return path;
    }

    public long size() {
      return size;
    }

    public String type() {
      return type;
    }

    /** Hex SHA-256 of the content, or null if the server doesn't know it. */
    public String sha256() {
      return sha256;
    }

    public Instant expires() {
      return expires;
    }

    @Override
    public String toString() {
      return "Download(" + url() + ", " + size + " bytes, " + type + ")";
    }

    /** The content as it arrives; resumed after connection loss; verified at the end. */
    public InputStream open() {
      return new Content();
    }

    /** The whole content in memory. */
    public byte[] readAllBytes() {
      if (size > Integer.MAX_VALUE - 8) throw new IllegalStateException("download too large for a byte[]: use open()");
      try (InputStream in = open()) {
        return in.readAllBytes();
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
    }

    /** Writes the content to a file (replaced if it exists). */
    public void saveTo(Path file) {
      try (InputStream in = open(); OutputStream out = Files.newOutputStream(file)) {
        in.transferTo(out);
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
    }

    private final class Content extends InputStream {
      private final MessageDigest digest;
      private InputStream current;
      private long received;
      private long skip;
      private String etag;
      private int failures;
      private boolean finished;

      Content() {
        try {
          digest = MessageDigest.getInstance("SHA-256");
        } catch (GeneralSecurityException e) {
          throw new IllegalStateException(e);
        }
      }

      private void connect() throws IOException {
        HttpRequest.Builder request = client.request(url(), null).GET();
        if (received > 0) {
          request.header("range", "bytes=" + received + "-");
          if (etag != null) request.header("if-range", etag);
        }
        Res res = client.exchange(request.build());
        if (res.status() >= 400) throw problem(res.status(), readBody(res.body(), MAX_MESSAGE));
        skip = 0;
        if (received == 0) {
          if (res.status() != 200) fail(res, "download answered " + res.status());
          etag = res.headers().firstValue("etag").orElse(null);
        } else if (res.status() == 206) {
          if (!res.headers().firstValue("content-range").orElse("").startsWith("bytes " + received + "-")) fail(res, "download resumed at the wrong offset");
        } else if (res.status() == 200 && etag != null && etag.equals(res.headers().firstValue("etag").orElse(null))) {
          skip = received; // the same content, sent whole: skip what we have
        } else {
          fail(res, "the download changed while resuming");
        }
        current = res.body();
      }

      private void fail(Res res, String detail) {
        try {
          res.body().close();
        } catch (IOException e) {
          // best effort
        }
        throw ApueException.badGateway("Bad Gateway", detail);
      }

      /** A lost or truncated connection: resume within the retry budget. */
      private void lost(IOException error) throws IOException {
        if (current != null) {
          try {
            current.close();
          } catch (IOException e) {
            // already broken
          }
          current = null;
        }
        if (++failures > client.retries) throw error;
        client.pause(client.backoffMs(failures));
      }

      @Override
      public int read() throws IOException {
        byte[] one = new byte[1];
        int n = read(one, 0, 1);
        return n < 0 ? -1 : one[0] & 0xff;
      }

      @Override
      public int read(byte[] buffer, int offset, int length) throws IOException {
        Objects.checkFromIndexSize(offset, length, buffer.length);
        if (length == 0) return 0;
        while (!finished) {
          int n;
          try {
            if (current == null) connect();
            n = current.read(buffer, offset, length);
          } catch (IOException e) {
            lost(e);
            continue;
          }
          if (n < 0) {
            current.close();
            current = null;
            if (received == size) {
              finish();
              break;
            }
            lost(new IOException("download ended after " + received + " of " + size + " bytes"));
            continue;
          }
          if (skip > 0) {
            int cut = (int) Math.min(skip, n);
            skip -= cut;
            if (cut == n) continue;
            System.arraycopy(buffer, offset + cut, buffer, offset, n - cut);
            n -= cut;
          }
          if (received + n > size) throw ApueException.badGateway("Bad Gateway", "download larger than its announced " + size + " bytes");
          received += n;
          digest.update(buffer, offset, n);
          return n;
        }
        return -1;
      }

      private void finish() {
        finished = true;
        if (sha256 != null && !sha256.equalsIgnoreCase(hex(digest.digest()))) {
          throw ApueException.badGateway("Bad Gateway", "download content does not match its SHA-256");
        }
      }

      @Override
      public void close() throws IOException {
        finished = true;
        if (current != null) current.close();
        current = null;
      }
    }
  }

  static String hex(byte[] bytes) {
    StringBuilder out = new StringBuilder(bytes.length * 2);
    for (byte b : bytes) out.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
    return out.toString();
  }

  // ---- the client -----------------------------------------------------------------------------

  /** Calls an apue API over one HttpClient (HTTP/2, TLS). Thread-safe. */
  public static class Base implements AutoCloseable {
    /** "No input" for ops whose input is void. */
    static final Object NONE = new Object();
    private final String base;
    private final URI origin;
    private final HttpClient http;
    private final Supplier<String> authorization;
    final int retries;
    private final long backoffMs;
    private final long maxBackoffMs;
    private final Duration timeout;

    protected Base(String baseUrl, Options options) {
      URI uri = URI.create(baseUrl.replaceAll("/+$", ""));
      if (!"https".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null) throw new IllegalArgumentException("apue servers speak HTTPS: " + baseUrl);
      if (uri.getRawQuery() != null || uri.getRawFragment() != null) throw new IllegalArgumentException("base URL with query or fragment: " + baseUrl);
      this.base = uri.toString();
      this.origin = URI.create(uri.getScheme() + "://" + uri.getRawAuthority() + "/");
      HttpClient.Builder builder = HttpClient.newBuilder()
          .version(HttpClient.Version.HTTP_2)
          .followRedirects(HttpClient.Redirect.NEVER)
          .connectTimeout(options.connectTimeout);
      if (options.sslContext != null) builder.sslContext(options.sslContext);
      this.http = builder.build();
      this.authorization = options.authorization;
      this.retries = options.retries;
      this.backoffMs = options.backoff.toMillis();
      this.maxBackoffMs = options.maxBackoff.toMillis();
      this.timeout = options.timeout;
    }

    /** The API's base URL. */
    public String baseUrl() {
      return base;
    }

    URI origin() {
      return origin;
    }

    /** Releases the HttpClient's connections (Java 21+; on 17 they close when idle). */
    @Override
    public void close() {
      if (http instanceof AutoCloseable closeable) {
        try {
          closeable.close();
        } catch (Exception e) {
          // best effort
        }
      }
    }

    // -- HTTP --

    /** A URI below the base URL: {@code pathAndQuery} starts with a slash and is encoded already. */
    URI uri(String pathAndQuery) {
      return URI.create(base + pathAndQuery);
    }

    HttpRequest.Builder request(URI uri, Duration deadline) {
      HttpRequest.Builder request = HttpRequest.newBuilder(uri)
          .header("accept", ACCEPT)
          .header("accept-encoding", "identity");
      String auth = authorization == null ? null : authorization.get();
      if (auth != null) request.header("authorization", auth);
      if (deadline != null) {
        request.header("apue-timeout", Long.toString(Math.max(1, deadline.toMillis())));
        request.timeout(deadline.plusSeconds(1)); // the server answers 504 first; this catches a silent one
      } else if (timeout != null) {
        request.timeout(timeout);
      }
      return request;
    }

    /** One request; a missing response within the deadline is a 504. */
    Res exchange(HttpRequest request) throws IOException {
      try {
        HttpResponse<InputStream> res = http.send(request, HttpResponse.BodyHandlers.ofInputStream());
        return new Res(res.statusCode(), res.headers(), res.body(), res.version());
      } catch (HttpTimeoutException e) {
        throw ApueException.of(504, DEADLINE_EXCEEDED, "Gateway Timeout", "no response within the deadline");
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new InterruptedIOException("interrupted");
      }
    }

    long backoffMs(int attempt) {
      double cap = Math.min((double) maxBackoffMs, backoffMs * Math.pow(2, attempt));
      return (long) (ThreadLocalRandom.current().nextDouble() * cap);
    }

    void pause(long ms) throws InterruptedIOException {
      try {
        Thread.sleep(ms);
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new InterruptedIOException("interrupted");
      }
    }

    /** Retry-After (RFC 9110 section 10.2.3): delay-seconds or an HTTP-date; null if absent or invalid. */
    static Long retryAfterMs(String header) {
      if (header == null) return null;
      String value = header.trim();
      if (value.matches("\\d{1,9}")) return Long.parseLong(value) * 1000;
      try {
        return Math.max(0, ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toEpochMilli() - System.currentTimeMillis());
      } catch (java.time.format.DateTimeParseException e) {
        return null;
      }
    }

    /** Sends; for safe and keyed calls retries connection loss, 429/503 and 409 with retryable: true. */
    Res send(HttpRequest request, boolean retry) {
      int attempt = 0;
      while (true) {
        Res res;
        try {
          res = exchange(request);
        } catch (InterruptedIOException e) {
          throw new UncheckedIOException(e);
        } catch (IOException e) {
          if (!retry || attempt >= retries) throw new UncheckedIOException(e);
          sleepQuietly(backoffMs(attempt++));
          continue;
        }
        if (!retry || attempt >= retries) return res;
        if (res.status() == 429 || res.status() == 503) {
          Long hinted = retryAfterMs(res.headers().firstValue("retry-after").orElse(null));
          readBody(res.body(), MAX_MESSAGE);
          sleepQuietly(hinted == null ? backoffMs(attempt) : Math.min(hinted, maxBackoffMs));
          attempt++;
          continue;
        }
        if (res.status() == 409 && res.mediaType().equals(PROBLEM_JSON)) {
          byte[] body = readBody(res.body(), MAX_MESSAGE);
          if (problem(409, body).retryable()) {
            sleepQuietly(backoffMs(attempt++));
            continue;
          }
          return new Res(res.status(), res.headers(), new ByteArrayInputStream(body), res.version());
        }
        return res;
      }
    }

    private void sleepQuietly(long ms) {
      try {
        pause(ms);
      } catch (InterruptedIOException e) {
        throw new UncheckedIOException(e);
      }
    }

    // -- uploads (bytes and file inputs) --

    /** Uploads content to /$uploads in one request; returns its reference {"$upload": id}. */
    public Map<String, Object> upload(FileInput file) {
      HttpRequest request = request(uri("/$uploads"), null)
          .header("upload-complete", "?1")
          .header("content-type", "application/octet-stream")
          .POST(file.publisher())
          .build();
      Res res;
      try {
        res = exchange(request);
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
      byte[] body = readBody(res.body(), MAX_MESSAGE);
      if (res.status() != 201) throw problem(res.status(), body);
      Object id;
      try {
        id = Json.object(Json.parse(body)).get("upload");
      } catch (IllegalArgumentException e) {
        id = null;
      }
      if (!(id instanceof String s) || !s.matches("[A-Za-z0-9_-]+")) throw ApueException.badGateway("Bad Gateway", "upload answered without an id");
      return Map.of("$upload", s);
    }

    public Map<String, Object> upload(byte[] data) {
      return upload(FileInput.of(data));
    }

    /** Deletes an upload (best effort for uploads the client made itself). */
    public void deleteUpload(Map<String, ?> ref) {
      if (!(ref.get("$upload") instanceof String id) || !id.matches("[A-Za-z0-9_-]+")) throw new IllegalArgumentException("not an upload reference: " + ref);
      try {
        Res res = exchange(request(uri("/$uploads/" + id), null).DELETE().build());
        byte[] body = readBody(res.body(), MAX_MESSAGE);
        if (res.status() >= 400 && res.status() != 404) throw problem(res.status(), body);
      } catch (IOException e) {
        throw new UncheckedIOException(e);
      }
    }

    private void deleteQuietly(List<Map<String, Object>> created) {
      for (Map<String, Object> ref : created) {
        try {
          deleteUpload(ref);
        } catch (RuntimeException e) {
          // they expire on their own
        }
      }
    }

    /** Replaces bytes and files in an encoded input with upload references. */
    private Object withUploads(Object value, List<Map<String, Object>> created) {
      if (value instanceof byte[] || value instanceof FileInput) {
        if (value instanceof FileInput file && file.upload != null) return Map.of("$upload", file.upload);
        Map<String, Object> ref = upload(value instanceof byte[] bytes ? FileInput.of(bytes) : (FileInput) value);
        created.add(ref);
        return ref;
      }
      if (value instanceof List<?> list) {
        List<Object> out = new ArrayList<>(list.size());
        for (Object item : list) out.add(withUploads(item, created));
        return out;
      }
      if (value instanceof Map<?, ?> map) {
        Map<Object, Object> out = new LinkedHashMap<>();
        for (Map.Entry<?, ?> entry : map.entrySet()) out.put(entry.getKey(), withUploads(entry.getValue(), created));
        return out;
      }
      return value;
    }

    // -- calls (used by the generated methods) --

    private HttpRequest prepare(Op op, Object value, CallOptions options) {
      if (op.effect.equals("safe") && (op.stream.equals("none") || op.stream.equals("server"))) {
        String path = "/" + op.name + (value == NONE ? "" : "?i=" + encodeComponent(Json.write(value)));
        if (path.length() <= MAX_GET_URL) return request(uri(path), options.timeout).GET().build();
      }
      HttpRequest.Builder request = request(uri("/" + op.name), options.timeout);
      if (!op.effect.equals("safe") && op.stream.equals("none")) {
        String key = options.idempotencyKey != null ? options.idempotencyKey : UUID.randomUUID().toString();
        request.header("idempotency-key", "\"" + key.replace("\\", "\\\\").replace("\"", "\\\"") + "\"");
      }
      if (value == NONE) return request.POST(HttpRequest.BodyPublishers.noBody()).build();
      return request.header("content-type", "application/json").POST(HttpRequest.BodyPublishers.ofString(Json.write(value), StandardCharsets.UTF_8)).build();
    }

    /** encodeURIComponent: UTF-8, everything but A-Z a-z 0-9 - _ . ! ~ * ' ( ) percent-encoded. */
    static String encodeComponent(String text) {
      StringBuilder out = new StringBuilder();
      for (byte b : text.getBytes(StandardCharsets.UTF_8)) {
        int c = b & 0xff;
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || "-_.!~*'()".indexOf(c) >= 0) {
          out.append((char) c);
        } else {
          out.append('%').append(Character.toUpperCase(Character.forDigit(c >> 4, 16))).append(Character.toUpperCase(Character.forDigit(c & 0xf, 16)));
        }
      }
      return out.toString();
    }

    /** A unary call: the output as parsed JSON (bytes restored), or null for void. */
    protected final Object $call(Op op, Object input, CallOptions options) {
      List<Map<String, Object>> created = new ArrayList<>();
      try {
        Object value = op.bytesIn && input != NONE ? withUploads(input, created) : input;
        HttpRequest request = prepare(op, value, options);
        // Non-safe unary calls always carry an Idempotency-Key, so every unary call may be retried.
        return new Reader(send(request, true), op.bytesOut).only();
      } finally {
        deleteQuietly(created);
      }
    }

    /** A server stream. */
    protected final <T> Stream<T> $stream(Op op, Object input, CallOptions options, Function<Object, T> decode) {
      List<Map<String, Object>> created = new ArrayList<>();
      try {
        Object value = op.bytesIn && input != NONE ? withUploads(input, created) : input;
        Res res = send(prepare(op, value, options), !op.effect.equals("unsafe"));
        return new Stream<>(new Reader(res, op.bytesOut), decode, created.isEmpty() ? null : () -> deleteQuietly(created));
      } catch (RuntimeException e) {
        deleteQuietly(created);
        throw e;
      }
    }

    private Reader streamRequest(Op op, Iterator<Object> inputs, CallOptions options) {
      FramePublisher body = new FramePublisher(inputs, op.bytesIn);
      HttpRequest request = request(uri("/" + op.name), options.timeout)
          .header("content-type", STREAM_JSON)
          .header("incremental", "?1")
          .POST(HttpRequest.BodyPublishers.fromPublisher(body))
          .build();
      try {
        return new Reader(send(request, false), op.bytesOut); // a request stream can't be replayed
      } catch (RuntimeException e) {
        if (body.failure != null) throw body.failure;
        throw e;
      }
    }

    /** A client stream: inputs are sent, then the single output is read (null for void). */
    protected final Object $clientStream(Op op, Iterator<Object> inputs, CallOptions options) {
      return streamRequest(op, inputs, options).only();
    }

    /** A bidi stream, half duplex: all inputs are sent before the outputs can be read. */
    protected final <T> Stream<T> $bidi(Op op, Iterator<Object> inputs, CallOptions options, Function<Object, T> decode) {
      return new Stream<>(streamRequest(op, inputs, options), decode, null);
    }
  }

  // ---- apue runtime: end ----
}
